import{_ as o,a as s}from"./chunks/basic-information.KdxxyYub.js";import{_ as n,m as i,k as r,ah as a,q as e}from"./chunks/framework.HEc25T99.js";const v=JSON.parse('{"title":"Identité de la plateforme","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"fr/developers/admin-panel/content-management/platform-identity.md","filePath":"src/fr/developers/admin-panel/content-management/platform-identity.md"}'),d={name:"fr/developers/admin-panel/content-management/platform-identity.md"},l=o+"#light-only",c=s+"#dark-only";function p(u,t,m,h,f,b){return r(),i("div",null,[...t[0]||(t[0]=[a('<h1 id="identite-de-la-plateforme" tabindex="-1">Identité de la plateforme <a class="header-anchor" href="#identite-de-la-plateforme" aria-label="Permalink to &quot;Identité de la plateforme&quot;">​</a></h1><p>Cette page regroupe les informations globales du site — celles consommées dans les templates via <code>getAppInformationValue()</code> (voir <a href="./../../development/utilities.html#usecontent">Utilitaires</a>) plutôt que définies dans une structure de section. Elle comporte trois onglets : <strong>Informations de base</strong>, <strong>Identité visuelle</strong> et <strong>Réseaux sociaux</strong>.</p><h2 id="informations-de-base" tabindex="-1">Informations de base <a class="header-anchor" href="#informations-de-base" aria-label="Permalink to &quot;Informations de base&quot;">​</a></h2>',3),e("p",null,[e("img",{src:l,alt:"Informations de base"}),e("img",{src:c,alt:"Informations de base"})],-1),a(`<table tabindex="0"><thead><tr><th>Champ</th><th>Description</th></tr></thead><tbody><tr><td>Nom du site</td><td>Nom affiché de la plateforme (clé <code>name</code>).</td></tr><tr><td>Email</td><td>Adresse de contact principale (clé <code>email</code>).</td></tr><tr><td>Téléphone</td><td>Numéro de contact principal (clé <code>phone</code>).</td></tr><tr><td>Adresse</td><td>Adresse physique (clé <code>address</code>).</td></tr><tr><td>Code postal</td><td>Code postal associé (clé <code>postalCode</code>).</td></tr><tr><td>Description</td><td>Présentation courte du site, traduisible par langue via le sélecteur en haut du champ (clé <code>description</code>).</td></tr></tbody></table><h2 id="identite-visuelle" tabindex="-1">Identité visuelle <a class="header-anchor" href="#identite-visuelle" aria-label="Permalink to &quot;Identité visuelle&quot;">​</a></h2><p>Onglet dédié aux médias et couleurs de marque : logo, logo monochrome, icône/favicon, icône monochrome, et couleurs primaire, secondaire et d&#39;accent (clés <code>logo</code>, <code>oneColorLogo</code>, <code>icon</code>, <code>oneColorIcon</code>, <code>primaryColor</code>, <code>secondaryColor</code>, <code>accentColor</code>). Ces valeurs alimentent notamment <code>appPrimaryColor</code>/<code>appSecondaryColor</code>/<code>appAccentColor</code>/<code>logo</code>/<code>icon</code> côté <code>useContent()</code>.</p><h2 id="reseaux-sociaux" tabindex="-1">Réseaux sociaux <a class="header-anchor" href="#reseaux-sociaux" aria-label="Permalink to &quot;Réseaux sociaux&quot;">​</a></h2><p>Un champ URL par réseau social supporté — ne renseigner que les réseaux réellement utilisés par le site, un champ vide n&#39;affiche pas l&#39;icône correspondante dans le Header/Footer :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>facebook, twitter, instagram, whatsapp, linkedin, youtube, pinterest, snapchat,</span></span>
<span class="line"><span>tiktok, telegram, discord, reddit, tumblr, vimeo, twitch, github, dribbble,</span></span>
<span class="line"><span>behance, medium, stackOverflow, threads, messenger, playstore, appstore</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Pour les développeurs</p><p>Ces valeurs peuvent aussi être renseignées en ligne de commande via <a href="./../../resources/cli.html#creopse-base-info-alias-info"><code>creopse base-info update</code></a> — pratique pour les peupler automatiquement lors de l&#39;intégration d&#39;un template plutôt que de repasser par cette page manuellement.</p></div><div class="tip custom-block"><p class="custom-block-title">Voir aussi</p><p>Une version orientée utilisateur final de cette rubrique existe dans le <a href="./../../../users/sections/content-management.html">Guide Utilisateur</a>.</p></div>`,8)])])}const x=n(d,[["render",p]]);export{v as __pageData,x as default};
